<script lang="ts">
  import { page } from '$app/state'; import { getConnector, pipelineErrorMessage, type ConnectorDefinition, type NexetlError } from '$lib/api/pipelines'; import PageHeader from '$lib/components/ui/PageHeader.svelte'; import Alert from '$lib/components/ui/Alert.svelte'; import LoadingState from '$lib/components/ui/LoadingState.svelte';
  let connector = $state<ConnectorDefinition | null>(null), error = $state(''), loading = $state(true);
  $effect(() => { const key = page.params.connectorKey; if (key) void load(key); }); async function load(key: string) { loading = true; try { connector = await getConnector(key); } catch (failure) { error = pipelineErrorMessage(failure as NexetlError); } finally { loading = false; } }
</script>
<svelte:head><title>{connector?.displayName ?? 'Connector'} | NEXETL</title></svelte:head>
{#if loading}<LoadingState />{:else if error}<Alert variant="error">{error}</Alert>{:else if connector}<PageHeader title={connector.displayName} description="Connector catalogue detail." /><dl><div><dt>Vendor</dt><dd>{connector.vendor}</dd></div><div><dt>Version</dt><dd>{connector.version}</dd></div><div><dt>Category</dt><dd>{connector.category}</dd></div><div><dt>Availability</dt><dd>{connector.availability === 'AVAILABLE' ? 'Available' : 'Coming later'}</dd></div><div><dt>Capabilities</dt><dd>{#each connector.capabilities as capability}<span class="tag">{capability}</span>{/each}</dd></div><div><dt>Description</dt><dd>{connector.description}</dd></div></dl><Alert variant="info">Connection configuration and credentials are not part of the current authoring increment.</Alert>{/if}
<style>dl{max-width:48rem;border-top:1px solid var(--border-default)}dl div{display:grid;grid-template-columns:10rem 1fr;gap:var(--space-4);border-bottom:1px solid var(--border-default);padding:var(--space-3) 0}dt{color:var(--text-muted)}dd{margin:0}.tag{display:inline-block;margin-right:.35rem;border:1px solid var(--border-default);border-radius:999px;padding:.08rem .45rem;color:var(--text-secondary);font-size:.78rem}@media(max-width:600px){dl div{grid-template-columns:1fr;gap:.2rem}}</style>
